			u16 const memory = source == 7 ? 0x5007 : std::array<u16, 4>{0, 1, 0x8000, 0xffff}[pattern];
			u16 const st1 = 0x800 | (flags & 1 ? 0x100 : 0) | (flags & 2 ? 0x200 : 0), address = 0x10 + source;
			u16 const mode = kind == 0 ? address : kind == 1 ? 0xf8 : 0xe7;
