			m_cpu->set_state_int(tms320c54x_device::STATE_AR2, 0x4455);
			m_cpu->set_state_int(tms320c54x_device::STATE_AR6, 0x0a03);
			m_cpu->set_state_int(tms320c54x_device::STATE_PC, 0x05e0);
