			osd_printf_info("TMS320C54x ROM4 FR decoder comparison: frames=32 samples=5120 mismatches=%u\n", m_rom4_pcm_mismatches);
			expect(!m_rom4_pcm_mismatches, "native FR decoder PCM matches independent codec");
